// Braced initialization prevents narrowing conversions
double x = 1.2, y = 3.4, z = 5.6;

// Error: sum of doubles may not be expressible as an int.
// This is a compile-time error, preventing potential data loss.
// int sum1 { x + y + z };

// OK: Parenthesis initialization allows the narrowing conversion.
// The result of (x + y + z) is truncated to an integer (10).
int sum2 (x + y + z);

// OK: Equals-sign initialization also allows the narrowing conversion.
// The result is also truncated to an integer (10).
int sum3 = x + y + z;
